import { useState, useEffect } from "react";
import { useAuth } from "../context/AuthContext";
import { useNavigate } from "react-router-dom";
import "../styles/login-ui.css";

export default function LoginPage() {
  const { login } = useAuth();
  const navigate = useNavigate();

  const [username, setUsername] = useState("");
  const [password, setPassword] = useState("");
  const [error, setError] = useState("");

  // slideshow images
  const images = [
    "/images/canteen1.jpg",
    "/images/canteen2.jpg",
    "/images/canteen3.jpg",
    "/images/canteen4.jpg",
  ];

  const [index, setIndex] = useState(0);

  useEffect(() => {
    const timer = setInterval(() => {
      setIndex(prev => (prev + 1) % images.length);
    }, 3000);
    return () => clearInterval(timer);
  }, []);

  const handleLogin = async () => {
    setError("");
    try {
      const ok = await login(username, password); // backend validation

      if (!ok) {
        setError("Invalid username or password. Please register first.");
      }
    } catch {
      setError("Login failed. Server error.");
    }
  };

  return (
    <div className="login-container">
      {/* LEFT – Login Form */}
      <div className="login-page">
        <h2>Digital Canteen Login</h2>

        <input
          placeholder="Username"
          value={username}
          onChange={e => setUsername(e.target.value)}
        />

        <input
          type="password"
          placeholder="Password"
          value={password}
          onChange={e => setPassword(e.target.value)}
        />

        {error && <div className="login-error">{error}</div>}

        <button onClick={handleLogin}>Login</button>

        <button
          className="secondary-btn"
          onClick={() => navigate("/register")}
        >
          New user? Register
        </button>

        <div className="login-hint">
          <p><b>Admin:</b> admin / admin@123</p>
          <p><b>Users:</b> Must register first</p>
        </div>
      </div>

      {/* RIGHT – Slideshow */}
      <div className="login-slider">
        {images.map((img, i) => (
          <img
            key={i}
            src={img}
            alt="Canteen"
            className={i === index ? "active" : ""}
          />
        ))}
        <div className="slider-overlay">
          <h3>Welcome to Digital Canteen</h3>
          <p>Fast • Smart • Cashless Ordering</p>
        </div>
      </div>
    </div>
  );
}
